import {
  DarkTheme,
  DefaultTheme,
  NavigationContainer,
} from "@react-navigation/native";
import { StatusBar } from "expo-status-bar";
import { useEffect, useRef, useState } from "react";
import { AppState, Linking, StyleSheet, Text, View } from "react-native";
import { GestureHandlerRootView } from "react-native-gesture-handler";
import { SafeAreaProvider } from "react-native-safe-area-context";

import { getErrorMessage } from "@typenotes/shared/errors";
import { parseSyncDeepLink } from "@typenotes/shared/sync-link";

import { bootCore } from "./core/boot";
import {
  jumpToHomePage,
  navigateToScreen,
  navigationRef,
  Stack,
} from "./navigation";
import { EditorScreen } from "./screens/editor-screen";
import { FeedScreen } from "./screens/feed-screen";
import { FolderScreen } from "./screens/folder-screen";
import { HomePagerScreen } from "./screens/home-pager";
import { LockScreen } from "./screens/lock-screen";
import {
  SettingsScreen,
  SettingsTranscriptionScreen,
  SettingsWorkingFoldersScreen,
} from "./screens/settings-screen";
import { useNotesStore } from "./state/notes-store";
import { isLocked, useSecurityStore } from "./state/security-store";
import { useSettingsStore } from "./state/settings-store";
import { useSyncStore } from "./state/sync-store";
import { useTheme } from "./theme";

type BootPhase = { state: "booting" } | { state: "ready" } | { state: "failed"; error: string };

const RootStack = () => {
  const theme = useTheme();
  return (
    <Stack.Navigator
      initialRouteName="Home"
      screenOptions={{
        headerStyle: { backgroundColor: theme.colors.background },
        headerTintColor: theme.colors.text,
        headerShadowVisible: false,
        contentStyle: { backgroundColor: theme.colors.background },
        // Swipe back from anywhere on the screen, not just the left edge —
        // still the native UIKit pop transition, driven natively by
        // react-native-screens' pan recognizer. It doesn't steal taps (a pan
        // needs clear horizontal movement before it claims the touch).
        fullScreenGestureEnabled: true,
        // Chevron-only back everywhere; screen titles say where you are, the
        // label naming the previous screen is noise.
        headerBackButtonDisplayMode: "minimal",
      }}
    >
      <Stack.Screen
        name="Home"
        component={HomePagerScreen}
        options={{ headerShown: false }}
      />
      <Stack.Screen name="Feed" component={FeedScreen} />
      <Stack.Screen
        name="Folder"
        component={FolderScreen}
        options={({ route }) => ({ title: route.params.title })}
      />
      <Stack.Screen
        name="Editor"
        component={EditorScreen}
        options={{
          // No title — the note text speaks for itself.
          title: "",
        }}
      />
      <Stack.Screen
        name="Settings"
        component={SettingsScreen}
        options={{ title: "Settings" }}
      />
      <Stack.Screen
        name="SettingsWorkingFolders"
        component={SettingsWorkingFoldersScreen}
        options={{ title: "Working Folders" }}
      />
      <Stack.Screen
        name="SettingsTranscription"
        component={SettingsTranscriptionScreen}
        options={{ title: "Transcription" }}
      />
    </Stack.Navigator>
  );
};

/**
 * A `type2://sync?...` link (from the desktop's QR code, scanned with the
 * system camera) drops the remote into the sync store and jumps to the Sync
 * page, which applies it. Pops back to the Home pager first in case a screen
 * is pushed on top; on cold start the pager picks the parked jump up on
 * mount.
 */
const handleSyncUrl = (url: string | null) => {
  const params = url ? parseSyncDeepLink(url) : null;
  if (!params) {
    return;
  }
  useSyncStore.getState().setPendingLink(params);
  navigateToScreen("Home");
  jumpToHomePage("sync", false);
};

export default function App() {
  const theme = useTheme();
  const [phase, setPhase] = useState<BootPhase>({ state: "booting" });
  const demoMode = useSettingsStore((s) => s.demoMode);
  const initialUrlHandled = useRef(false);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { demoMode: demo } = await bootCore();
        useSettingsStore.getState().setDemoMode(demo);
        await useSecurityStore.getState().load();
        // While encrypted + locked, content calls are rejected by the core —
        // the lock screen's unlock reloads these stores instead.
        if (!isLocked(useSecurityStore.getState().state)) {
          await useSettingsStore.getState().load();
          await useNotesStore.getState().refresh();
          // Best-effort — populates the menu's "last synced" label without
          // forcing the user through the Sync screen first.
          void useSyncStore.getState().refresh().catch(() => {});
        }
        if (!cancelled) {
          setPhase({ state: "ready" });
        }
      } catch (error) {
        if (!cancelled) {
          setPhase({ state: "failed", error: getErrorMessage(error) });
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  // Deep links while the app is running; the initial (cold-start) URL is
  // picked up in the container's onReady below.
  useEffect(() => {
    const subscription = Linking.addEventListener("url", ({ url }) =>
      handleSyncUrl(url)
    );
    return () => subscription.remove();
  }, []);

  // Auto-lock when the app goes to background (if enabled in security prefs).
  useEffect(() => {
    const subscription = AppState.addEventListener("change", (next) => {
      const security = useSecurityStore.getState();
      if (
        next === "background" &&
        security.state?.encryption_enabled &&
        security.state.auto_lock_on_background
      ) {
        void security.lock();
      }
    });
    return () => subscription.remove();
  }, []);

  const securityState = useSecurityStore((s) => s.state);
  const locked = isLocked(securityState);

  if (phase.state !== "ready") {
    return (
      <View style={[styles.boot, { backgroundColor: theme.colors.background }]}>
        {phase.state === "failed" ? (
          <Text style={[styles.bootError, { color: theme.colors.danger }]}>
            {phase.error}
          </Text>
        ) : null}
        <StatusBar style={theme.dark ? "light" : "dark"} />
      </View>
    );
  }

  if (locked) {
    return (
      <SafeAreaProvider>
        <LockScreen />
        <StatusBar style={theme.dark ? "light" : "dark"} />
      </SafeAreaProvider>
    );
  }

  return (
    <GestureHandlerRootView style={styles.root}>
      <SafeAreaProvider>
        <NavigationContainer
          ref={navigationRef}
          theme={theme.dark ? DarkTheme : DefaultTheme}
          onReady={() => {
            if (!initialUrlHandled.current) {
              initialUrlHandled.current = true;
              void Linking.getInitialURL().then(handleSyncUrl);
            }
          }}
        >
          <RootStack />
        </NavigationContainer>
        {demoMode ? (
          <View style={[styles.demoBanner, { backgroundColor: theme.colors.accent }]}>
            <Text style={styles.demoBannerText}>
              Demo mode — native core not linked, notes are not persisted
            </Text>
          </View>
        ) : null}
        <StatusBar style={theme.dark ? "light" : "dark"} />
      </SafeAreaProvider>
    </GestureHandlerRootView>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
  boot: { flex: 1, alignItems: "center", justifyContent: "center", padding: 24 },
  bootError: { fontSize: 15, textAlign: "center" },
  demoBanner: {
    position: "absolute",
    bottom: 0,
    left: 0,
    right: 0,
    paddingVertical: 4,
    alignItems: "center",
  },
  demoBannerText: { color: "#ffffff", fontSize: 12, fontWeight: "600" },
});
import {
  CommonActions,
  createNavigationContainerRef,
} from "@react-navigation/native";
import { createNativeStackNavigator } from "@react-navigation/native-stack";

// One native stack whose root is the Home pager: Menu | Capture | Sync live
// side by side in a native horizontal pager (tab behavior, no visible tab
// bar) — swipe left/right anywhere to move between them, with the capture
// page in the middle as the boot landing. Everything else (Feed, Folder,
// Editor, Settings…) is pushed onto the stack above the pager, so the native
// back swipe from those lands back on whatever page was showing.
export type RootStackParamList = {
  Home: undefined;
  Feed: undefined;
  Folder: { path: string; title: string };
  Editor: { path: string; title?: string };
  Settings: undefined;
  SettingsWorkingFolders: undefined;
  SettingsTranscription: undefined;
};

export const Stack = createNativeStackNavigator<RootStackParamList>();

/** Container ref so deep-link handling can navigate from outside React. */
export const navigationRef = createNavigationContainerRef<RootStackParamList>();

export const navigateToScreen = <Screen extends keyof RootStackParamList>(
  screen: Screen,
  params?: RootStackParamList[Screen]
) => {
  if (navigationRef.isReady()) {
    navigationRef.dispatch(CommonActions.navigate({ name: screen, params }));
  }
};

// ---- Home pager plumbing ---------------------------------------------------

export type HomePage = "menu" | "capture" | "sync";

export const HOME_PAGE_INDEX: Record<HomePage, number> = {
  menu: 0,
  capture: 1,
  sync: 2,
};

// Structural type instead of importing PagerView here: keeps this module
// free of the native dependency (only home-pager.tsx touches it).
type HomePagerHandle = {
  setPage: (index: number) => void;
  setPageWithoutAnimation: (index: number) => void;
};

/** Set by HomePagerScreen on mount; null while the pager isn't attached. */
export const homePagerRef: { current: HomePagerHandle | null } = {
  current: null,
};

// A jump requested before the pager mounted (cold-start deep link) — the
// pager consumes it on mount instead of landing on the default page.
let pendingHomePage: HomePage | null = null;

export const consumePendingHomePage = (): HomePage | null => {
  const page = pendingHomePage;
  pendingHomePage = null;
  return page;
};

/**
 * Move the Home pager to a page — the buttons' and deep links' counterpart
 * of the swipe. Callers navigating from a pushed screen should also
 * `navigateToScreen("Home")` to pop back to the pager first.
 */
export const jumpToHomePage = (page: HomePage, animated = true) => {
  const pager = homePagerRef.current;
  if (!pager) {
    pendingHomePage = page;
    return;
  }
  if (animated) {
    pager.setPage(HOME_PAGE_INDEX[page]);
  } else {
    pager.setPageWithoutAnimation(HOME_PAGE_INDEX[page]);
  }
};
// The stack root: Menu | Capture | Sync as three pages of a native
// horizontal pager with no visible tab bar. Swiping left/right anywhere
// moves between them with UIScrollView paging physics, both directions
// finger-driven with live content — this replaces the old push/pop model and
// its hand-rolled gesture-driven preview overlays. Buttons and deep links
// jump pages via jumpToHomePage (navigation.ts).

import { useEffect, useRef, useState } from "react";
import { StyleSheet, View } from "react-native";
import PagerView from "react-native-pager-view";

import {
  consumePendingHomePage,
  HOME_PAGE_INDEX,
  homePagerRef,
  jumpToHomePage,
} from "../navigation";
import { CaptureScreen } from "./capture-screen";
import { MenuScreen } from "./menu-screen";
import { SyncScreen } from "./sync-screen";

export const HomePagerScreen = () => {
  const [activeIndex, setActiveIndex] = useState(HOME_PAGE_INDEX.capture);

  // Whether the menu page is at least partially on screen. This (not
  // onPageSelected) drives MenuScreen's freeze/thaw: the menu must catch up
  // with the stores the moment a drag starts revealing it — waiting for the
  // swipe to settle would show stale lists mid-swipe. onPageScroll fires on
  // every drag frame, so gate the state change behind a ref.
  const [menuEngaged, setMenuEngaged] = useState(false);
  const menuEngagedRef = useRef(false);

  useEffect(() => {
    // A cold-start deep link may have requested a page before the pager
    // attached (jumpToHomePage parks it) — apply it now, unanimated.
    const pending = consumePendingHomePage();
    if (pending) {
      jumpToHomePage(pending, false);
      setActiveIndex(HOME_PAGE_INDEX[pending]);
    }
    return () => {
      homePagerRef.current = null;
    };
  }, []);

  return (
    <PagerView
      ref={(pager) => {
        homePagerRef.current = pager;
      }}
      style={styles.pager}
      initialPage={HOME_PAGE_INDEX.capture}
      keyboardDismissMode="on-drag"
      onPageSelected={(event) => setActiveIndex(event.nativeEvent.position)}
      onPageScroll={(event) => {
        // position/offset describe the scroll window: the menu (page 0) is
        // on screen exactly when the pager sits at or scrolls within [0, 1).
        const engaged = event.nativeEvent.position === HOME_PAGE_INDEX.menu;
        if (engaged !== menuEngagedRef.current) {
          menuEngagedRef.current = engaged;
          setMenuEngaged(engaged);
        }
      }}
    >
      {/* collapsable=false: the pager needs real native views as pages. */}
      <View key="menu" style={styles.page} collapsable={false}>
        <MenuScreen active={menuEngaged} />
      </View>
      <View key="capture" style={styles.page} collapsable={false}>
        <CaptureScreen active={activeIndex === HOME_PAGE_INDEX.capture} />
      </View>
      <View key="sync" style={styles.page} collapsable={false}>
        <SyncScreen />
      </View>
    </PagerView>
  );
};

const styles = StyleSheet.create({
  pager: { flex: 1 },
  page: { flex: 1 },
});

