// The capture page's note lifecycle, kept free of React and React Native so
// it can be unit-tested. Mirrors the desktop editor's rules:
//
// - the note file is created lazily, on the first non-empty change
// - subsequent edits are debounced writes (against the created path)
// - committing (swipe up / navigating away) flushes pending writes
// - committing an *emptied* note deletes the file (empty-note cleanup)
//
// All storage calls are serialized on an internal chain so a slow createNote
// can never race a following write or delete.

export type CaptureStorage = {
  createNote(content: string): Promise<string>;
  writeNote(path: string, content: string): Promise<void>;
  deleteNote(path: string): Promise<void>;
};

export const CAPTURE_DEBOUNCE_MS = 500;

export class CaptureSession {
  private path: string | null = null;
  private content = "";
  private dirty = false;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private chain: Promise<void> = Promise.resolve();

  constructor(
    private storage: CaptureStorage,
    private debounceMs: number = CAPTURE_DEBOUNCE_MS
  ) {}

  /** The path of the note backing the current page, if one exists yet. */
  currentPath(): string | null {
    return this.path;
  }

  onChange(text: string) {
    this.content = text;
    this.dirty = true;
    if (this.timer) {
      clearTimeout(this.timer);
    }
    this.timer = setTimeout(() => {
      this.timer = null;
      void this.flush();
    }, this.debounceMs);
  }

  /** Persist the current content (creating the note on first flush). */
  flush(): Promise<void> {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    this.chain = this.chain.then(async () => {
      // Loop: content may change while a write is in flight.
      while (this.dirty) {
        const content = this.content;
        if (!this.path && !content.trim()) {
          // Nothing worth creating yet.
          this.dirty = false;
          return;
        }
        if (!this.path) {
          this.path = await this.storage.createNote(content);
        } else {
          await this.storage.writeNote(this.path, content);
        }
        this.dirty = content !== this.content;
      }
    });
    return this.chain;
  }

  /**
   * Finish the current page: flush, delete the note if it ended up empty,
   * and reset for a fresh blank page. Returns the committed note's path,
   * or null when nothing was kept.
   */
  async commit(): Promise<string | null> {
    await this.flush();
    const path = this.path;
    const keep = Boolean(path) && Boolean(this.content.trim());
    if (path && !keep) {
      await (this.chain = this.chain.then(() => this.storage.deleteNote(path)));
    }
    this.path = null;
    this.content = "";
    this.dirty = false;
    return keep ? path : null;
  }
}
import { describe, expect, it, vi } from "vitest";

import { CaptureSession, type CaptureStorage } from "./capture";

const makeStorage = () => {
  const notes = new Map<string, string>();
  let counter = 0;
  const storage: CaptureStorage = {
    createNote: vi.fn(async (content: string) => {
      counter += 1;
      const path = `Feed/note-${counter}.md`;
      notes.set(path, content);
      return path;
    }),
    writeNote: vi.fn(async (path: string, content: string) => {
      notes.set(path, content);
    }),
    deleteNote: vi.fn(async (path: string) => {
      notes.delete(path);
    }),
  };
  return { storage, notes };
};

describe("CaptureSession", () => {
  it("creates the note once on first flush, then writes", async () => {
    const { storage, notes } = makeStorage();
    const session = new CaptureSession(storage, 10_000);

    session.onChange("h");
    session.onChange("hello");
    await session.flush();
    expect(storage.createNote).toHaveBeenCalledTimes(1);
    expect(notes.get("Feed/note-1.md")).toBe("hello");

    session.onChange("hello world");
    await session.flush();
    expect(storage.createNote).toHaveBeenCalledTimes(1);
    expect(storage.writeNote).toHaveBeenCalledWith("Feed/note-1.md", "hello world");
  });

  it("does not create anything for whitespace-only content", async () => {
    const { storage } = makeStorage();
    const session = new CaptureSession(storage, 10_000);
    session.onChange("   \n");
    await session.flush();
    expect(storage.createNote).not.toHaveBeenCalled();
    expect(await session.commit()).toBeNull();
  });

  it("commit returns the path and resets for a fresh page", async () => {
    const { storage } = makeStorage();
    const session = new CaptureSession(storage, 10_000);
    session.onChange("first note");
    expect(await session.commit()).toBe("Feed/note-1.md");
    expect(session.currentPath()).toBeNull();

    session.onChange("second note");
    expect(await session.commit()).toBe("Feed/note-2.md");
    expect(storage.createNote).toHaveBeenCalledTimes(2);
  });

  it("deletes the note when committed empty (empty-note cleanup)", async () => {
    const { storage, notes } = makeStorage();
    const session = new CaptureSession(storage, 10_000);
    session.onChange("typo");
    await session.flush();
    session.onChange("");
    expect(await session.commit()).toBeNull();
    expect(storage.deleteNote).toHaveBeenCalledWith("Feed/note-1.md");
    expect(notes.size).toBe(0);
  });

  it("serializes a slow create against following writes", async () => {
    const notes = new Map<string, string>();
    let release!: () => void;
    const gate = new Promise<void>((resolve) => {
      release = resolve;
    });
    const storage: CaptureStorage = {
      createNote: async (content) => {
        await gate;
        notes.set("Feed/slow.md", content);
        return "Feed/slow.md";
      },
      writeNote: async (path, content) => {
        notes.set(path, content);
      },
      deleteNote: async () => {},
    };
    const session = new CaptureSession(storage, 10_000);
    session.onChange("a");
    const first = session.flush();
    session.onChange("ab");
    const second = session.flush();
    release();
    await Promise.all([first, second]);
    expect(notes.get("Feed/slow.md")).toBe("ab");
  });

  it("debounces writes on its own timer", async () => {
    vi.useFakeTimers();
    try {
      const { storage } = makeStorage();
      const session = new CaptureSession(storage, 500);
      session.onChange("h");
      session.onChange("hi");
      expect(storage.createNote).not.toHaveBeenCalled();
      await vi.advanceTimersByTimeAsync(499);
      expect(storage.createNote).not.toHaveBeenCalled();
      await vi.advanceTimersByTimeAsync(1);
      expect(storage.createNote).toHaveBeenCalledTimes(1);
      expect(storage.createNote).toHaveBeenCalledWith("hi");
    } finally {
      vi.useRealTimers();
    }
  });
});

