# @typenotes/mobile-core

The React Native app's bridge to the shared Rust core (`crates/type-ffi`,
UniFFI bindings over `crates/type-core`).

## How it fits together

```
apps/mobile  ──imports──▶  core-api.ts   (typed facade, JSON marshalling)
                              │
                              ▼
                          raw-core.ts    (RawCore interface + setRawCore seam)
                              ▲
              ┌───────────────┴────────────────┐
   src/generated/* (ubrn codegen,       mock-core.ts (in-memory,
   real Rust core — Mac build only)     demo mode / tests / Expo Go)
```

- **`src/core-api.ts`** — what the app imports. Typed functions
  (`getTree(): Promise<FolderNode>`, `gitPush(args)`, …) that serialize to the
  same serde JSON the desktop Tauri commands use (types from
  `@typenotes/shared/types`).
- **`src/raw-core.ts`** — the `RawCore` interface mirroring the UniFFI exports
  one-to-one, plus `setRawCore()`. The app wires an implementation at startup.
- **`src/mock-core.ts`** — in-memory `RawCore` used by tests and as demo mode
  when the native module isn't linked. Nothing persists.

This layout keeps `tsc`, `vitest`, and Expo Go working with **no native
builds** — the generated turbo module is only required for a real device build.

## Generating the native module (Mac only)

Prerequisites: Xcode (+ `rustup target add aarch64-apple-ios aarch64-apple-ios-sim`),
and/or Android Studio + NDK (+ `rustup target add aarch64-linux-android armv7-linux-androideabi`).

```sh
# One-time, in this package. --no-save on purpose: the tool is Mac-only,
# declaring it would make every Linux/CI npm install pull it in.
npm install --no-save uniffi-bindgen-react-native@0.31.0-3

npm run codegen:ios          # simulator slices only — the fast default
npm run codegen:ios:device   # device + simulator (needed for `expo run:ios --device`)
npm run codegen:android
```

`codegen:ios` builds `--sim-only`, so the resulting xcframework has no device
slice — rerun `codegen:ios:device` before installing on a physical phone.
From the repo root, `npm run mobile:ios` chains `codegen:ios` + `expo run:ios`
(the full "Rust changed, rebuild the dev client" one-liner).

This produces `src/generated/` (TS bindings), `cpp/generated/` (JSI glue), and
the `ios/` / `android/` library projects. Then wire the generated module in
the app instead of the mock (`apps/mobile/src/core/boot.ts`):

```ts
import { setRawCore } from "@typenotes/mobile-core/raw-core";
import * as generated from "@typenotes/mobile-core/generated";
setRawCore(generated);
```

The generated function names match `RawCore` (uniffi camelCases the Rust
snake_case exports). If a signature drifts after changing `crates/type-ffi`,
update `raw-core.ts` and `core-api.ts` to match — the desktop commands and
`crates/type-ffi/src/tests.rs` are the source of truth for the JSON shapes.

Generated output is gitignored; regenerate after every `crates/type-ffi`
change. Finally run `npx pod-install` in `apps/mobile/ios` after an Expo
prebuild (see `apps/mobile/README.md`).

## Transcription providers

`queueProviderTranscriptions(provider)` passes a host-side implementation of
the FFI foreign trait to the Rust queue worker — this is how native on-device
speech recognition plugs in without touching core:

```ts
await queueProviderTranscriptions({
  id: () => "apple-speech",
  transcribe: (audioPath) => recognizeWithSFSpeech(audioPath),
});
```

Use it when the active working folder's `transcription_mode` is `"native"`.
`"assemblyai"` uses `queueRecordingTranscriptions()` (cloud); `"desktop"`
leaves recordings `pending` so a synced desktop transcribes them with local
Whisper; `"off"` never queues automatically.
// In-memory RawCore implementation. Two consumers:
//
// 1. Tests — core-api and the app's stores run against it without native code.
// 2. Demo mode — when the generated turbo module isn't linked (Expo Go, CI,
//    simulators without a Rust toolchain), the app can boot against this and
//    stay fully interactive; the UI shows a "demo mode" banner.
//
// Behavior mirrors the Rust core where the UI can observe it (system folders,
// note lifecycle, pending → completed transcription statuses, the
// transcription_mode merge rule), but it is deliberately a toy: nothing
// persists, git operations only simulate success.

import type { FolderNode, NoteMeta, ProfileSettings } from "@typenotes/shared/types";

import type { RawCore, RawTranscriptionProvider } from "./raw-core";

type MockNote = {
  content: string;
  meta: NoteMeta;
};

const FEED = "Feed";
const ARCHIEVE = "Archieve"; // intentional typo, matches persisted data
const RECORDINGS = "Recordings"; // hidden storage folder
const ATTACHMENTS = "Attachments"; // hidden storage folder

const defaultProfileSettings = (): ProfileSettings => ({
  git_remote_url: "",
  git_branch: "main",
  git_username: "",
  git_password: "",
  git_commit_message: "Sync notes",
  git_trusted_ssh_host: "",
  git_trusted_ssh_host_key_sha256: "",
  mobile_auto_transcription_enabled: true,
  mobile_auto_handwriting_ocr_enabled: true,
  transcription_mode: null,
});

const defaultAppConfig = () => ({
  assemblyai_api_key: "",
  whisper_model: "large-v3",
  handwriting_ocr_provider: "local",
  local_ocr_model_path: "",
  openai_api_key: "",
  openai_model: "gpt-4.1-mini",
  huggingface_api_key: "",
  huggingface_model: "microsoft/trocr-base-handwritten",
  note_file_name_format: "utc_timestamp_slug",
});

const parentOf = (path: string) => {
  const index = path.lastIndexOf("/");
  return index === -1 ? "" : path.slice(0, index);
};

const nameOf = (path: string) => {
  const index = path.lastIndexOf("/");
  return index === -1 ? path : path.slice(index + 1);
};

const timestampSlug = (ms: number) =>
  new Date(ms).toISOString().replace(/\.\d{3}Z$/, "Z").replace(/:/g, "-");

export type MockCoreOptions = {
  /** Seed a few demo notes so the UI has content on first launch. */
  seed?: boolean;
  now?: () => number;
};

export const createMockCore = (options: MockCoreOptions = {}): RawCore => {
  const now = options.now ?? Date.now;

  let folders = new Set<string>([FEED, ARCHIEVE, RECORDINGS, ATTACHMENTS]);
  let notes = new Map<string, MockNote>();
  let audio = new Map<string, { base64: string; mimeType: string }>();
  let images = new Map<string, { base64: string; mimeType: string }>();
  let counter = 0;

  let profileSettings = defaultProfileSettings();
  let appConfig = defaultAppConfig();
  let commits: { id: string; summary: string; authored_ms: number }[] = [];
  let sshPublicKey: string | null = null;

  let security = {
    encryption_enabled: false,
    locked: false,
    auto_lock_on_background: false,
  };
  let unlockPassword = "";
  let panicPassword = "";

  const newNote = (folder: string, content: string, ms: number, extra?: Partial<NoteMeta>) => {
    counter += 1;
    folders.add(folder);
    const path = `${folder}/${timestampSlug(ms)}-note-${counter}.md`;
    notes.set(path, {
      content,
      meta: { created_ms: ms, updated_ms: ms, ...extra },
    });
    return path;
  };

  const seed = () => {
    if (!options.seed) {
      return;
    }
    const base = now();
    newNote(FEED, "Welcome to Type\n\nThis build is running the in-memory demo core — notes are not persisted.", base - 3 * 86_400_000);
    newNote(FEED, "Swipe up on this page to file it away and get a fresh blank page.", base - 86_400_000);
    newNote("Ideas", "Ship the mobile app.", base - 3_600_000);
  };
  seed();

  const buildTree = (): FolderNode => {
    const children = new Map<string, FolderNode>();
    const ensureFolderNode = (path: string): FolderNode => {
      if (!path) {
        throw new Error("root is built separately");
      }
      const existing = children.get(path);
      if (existing) {
        return existing;
      }
      const node: FolderNode = { name: nameOf(path), path, children: [], notes: [] };
